 "content": "from collections import deque


def transform(grid):
    """Fill zero-valued cells enclosed by color-2 outlines with color 8."""
    h, w = len(grid), len(grid[0])
    exterior = set()
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and (r, c) not in exterior:
                exterior.add((r, c))
                q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and (r, c) not in exterior:
                exterior.add((r, c))
                q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and (nr, nc) not in exterior:
                exterior.add((nr, nc))
                q.append((nr, nc))
    return [[8 if grid[r][c] == 0 and (r, c) not in exterior else grid[r][c]
             for c in range(w)] for r in range(h)]


if __name__ == "__main__":
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
