def transform(grid):
    """For each zero region enclosed by 2s, fill it with its size modulo 10."""
    h, w = len(grid), len(grid[0])
    exterior = set()
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and (r, c) not in exterior:
                exterior.add((r, c))
                q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and (r, c) not in exterior:
                exterior.add((r, c))
                q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and (nr, nc) not in exterior:
                exterior.add((nr, nc))
                q.append((nr, nc))

    result = [row[:] for row in grid]
    seen = set(exterior)
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            region = []
            q = deque([(r, c)])
            seen.add((r, c))
            while q:
                cr, cc = q.popleft()
                region.append((cr, cc))
                for nr, nc in ((cr - 1, cc), (cr + 1, cc), (cr, cc - 1), (cr, cc + 1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        q.append((nr, nc))
            if region:
                color = len(region) % 10
                for cr, cc in region:
                    result[cr][cc] = color
