 "content": "from collections import deque


def transform(grid):
    """Fill enclosed square cavities according to the observed size-color rule."""
    h, w = len(grid), len(grid[0])
    outside = set()
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and (r, c) not in outside:
                outside.add((r, c))
                q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and (r, c) not in outside:
                outside.add((r, c))
                q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and (nr,nc) not in outside:
                outside.add((nr,nc)); q.append((nr,nc))
    seen = set(outside)
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r,c) in seen:
                continue
            region=[]; q=deque([(r,c)]); seen.add((r,c))
            while q:
                cr,cc=q.popleft(); region.append((cr,cc))
                for nr,nc in ((cr-1,cc),(cr+1,cc),(cr,cc-1),(cr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and (nr,nc) not in seen:
                        seen.add((nr,nc)); q.append((nr,nc))
            # Demos map a 3-wide interior to 8, and a 5-wide interior to 4.
            # Continue that alternating pattern; preserve the center marker.
            width = max(x for x,y in region)-min(x for x,y in region)+1
            color = (14 - 2*width) % 10
            for cr,cc in region: out[cr][cc]=color
    return out

if __name__ == '__main__':
    import json,sys
    print(json.dumps(transform(json.load(sys.stdin))))
