 "content": "from collections import deque

def transform(grid):
    h,w=len(grid),len(grid[0]); outside=set(); q=deque()
    for r in range(h):
        for c in (0,w-1):
            if grid[r][c]==0 and (r,c) not in outside: outside.add((r,c));q.append((r,c))
    for c in range(w):
        for r in (0,h-1):
            if grid[r][c]==0 and (r,c) not in outside: outside.add((r,c));q.append((r,c))
    while q:
        r,c=q.popleft()
        for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0<=nr<h and 0<=nc<w and grid[nr][nc]==0 and (nr,nc) not in outside:
                outside.add((nr,nc));q.append((nr,nc))
    seen=set(outside);out=[row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=0 or (r,c) in seen: continue
            reg=[];q=deque([(r,c)]);seen.add((r,c))
            while q:
                a,b=q.popleft();reg.append((a,b))
                for x,y in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
                    if 0<=x<h and 0<=y<w and grid[x][y]==0 and (x,y) not in seen:
                        seen.add((x,y));q.append((x,y))
            color={8:8,24:4,48:0}.get(len(reg),len(reg)%10)
            for a,b in reg: out[a][b]=color
    return out

if __name__=='__main__':
    import json,sys
    print(json.dumps(transform(json.load(sys.stdin))))
